select date_trunc('month', event_time) as activity_month, date_trunc('week', event_time) as week_start, date_trunc('year', event_time) as year_start, max(duration_sec) as max_duration_sec, percentile_approx(duration_sec, array(0.25, 0.5, 0.75)) as duration_sec_quartiles, avg(duration_sec) as avg_duration_sec, sum(case when event_type = 'search' then duration_sec else 0 end) as search_duration_sec, grouping(date_trunc('month', event_time)) as grouping_level from web_events group by rollup (date_trunc('month', event_time), date_trunc('week', event_time), date_trunc('year', event_time)) order by activity_month nulls first
